#pragma once
#include <stdint.h>

// Anti-aliased Unicode bitmap font (4 bits/pixel, two pixels per byte, row-major,
// each glyph starts on a byte boundary). Generated by tools/gen_font.py.
struct UGlyph {
  uint16_t cp;      // Unicode code point (table is sorted by cp)
  uint32_t off;     // byte offset into the bitmap
  uint8_t  w, h;    // bitmap size
  uint8_t  adv;     // cursor advance
  int8_t   xo, yo;  // bitmap offset from the cursor / baseline (yo is negative above the baseline)
};

struct UFont {
  const uint8_t* bmp;
  const UGlyph*  glyphs;
  uint16_t       count;
  uint8_t        lineHeight;
  uint8_t        ascent;
};

extern const UFont UF_SMALL;   // body text
extern const UFont UF_BOLD;    // titles
